## Introduction

Les interfaces peuvent aussi être paramétrées par des types.

## Concept

```ts
interface Repository<T> {
  getById(id: string): T | undefined;
  save(entity: T): void;
  getAll(): T[];
}

interface User {
  id: string;
  name: string;
}

const userRepo: Repository<User> = {
  getById: (id) => undefined,
  save: (user) => {},
  getAll: () => []
